//! Job management tools.//!//! These tools allow the LLM to manage jobs://! - Create new jobs/tasks (with optional sandbox delegation)//! - List existing jobs//! - Check job status//! - Cancel running jobsuse std::path::PathBuf;use std::sync::Arc;use std::time::Duration;use async_trait::async_trait;use chrono::Utc;use tokio::sync::RwLock;use uuid::Uuid;use crate::bootstrap::ironclaw_base_dir;use crate::channels::IncomingMessage;use crate::channels::web::types::SseEvent;use crate::context::{ContextManager, JobContext, JobState};use crate::db::Database;use crate::history::SandboxJobRecord;use crate::orchestrator::auth::CredentialGrant;use crate::orchestrator::job_manager::{ContainerJobManager, JobMode};use crate::secrets::SecretsStore;use crate::tools::tool::{ApprovalRequirement, Tool, ToolError, ToolOutput, require_str};/// Lazy scheduler reference, filled after Agent::new creates the Scheduler.////// Solves the chicken-and-egg: tools are registered before the Scheduler exists/// (Scheduler needs the ToolRegistry). Created empty, filled after Agent::new.pub type SchedulerSlot = Arc<RwLock<Option<Arc<crate::agent::Scheduler>>>>;/// Resolve a job ID from a full UUID or a short prefix (like git short SHAs).////// Tries full UUID parse first. If that fails, treats the input as a hex prefix/// and searches the context manager for a unique match.async fn resolve_job_id(input: &str, context_manager: &ContextManager) -> Result<Uuid, ToolError> {    // Fast path: full UUID    if let Ok(id) = Uuid::parse_str(input) {        return Ok(id);    }    // Require a minimum prefix length to limit brute-force enumeration.    if input.len() < 4 {        return Err(ToolError::InvalidParameters(            "job ID prefix must be at least 4 hex characters".to_string(),        ));    }    // Prefix match against known jobs    let input_lower = input.to_lowercase();    let all_ids = context_manager.all_jobs().await;    let matches: Vec<Uuid> = all_ids        .into_iter()        .filter(|id| {            let hex = id.to_string().replace('-', "");            hex.starts_with(&input_lower)        })        .collect();    match matches.len() {        1 => Ok(matches[0]),        0 => Err(ToolError::InvalidParameters(format!(            "no job found matching prefix '{}'",            input        ))),        n => Err(ToolError::InvalidParameters(format!(            "ambiguous prefix '{}' matches {} jobs, provide more characters",            input, n        ))),    }}/// Tool for creating a new job.////// When sandbox deps are injected (via `with_sandbox`), the tool automatically/// delegates execution to a Docker container. Otherwise it creates an in-memory/// job via the ContextManager. The LLM never needs to know the difference.pub struct CreateJobTool {    context_manager: Arc<ContextManager>,    /// Lazy scheduler for dispatching local (non-sandbox) jobs.    scheduler_slot: Option<SchedulerSlot>,    job_manager: Option<Arc<ContainerJobManager>>,    store: Option<Arc<dyn Database>>,    /// Broadcast sender for job events (used to subscribe a monitor).    event_tx: Option<tokio::sync::broadcast::Sender<(Uuid, SseEvent)>>,    /// Injection channel for pushing messages into the agent loop.    inject_tx: Option<tokio::sync::mpsc::Sender<IncomingMessage>>,    /// Encrypted secrets store for validating credential grants.    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,}impl CreateJobTool {    pub fn new(context_manager: Arc<ContextManager>) -> Self {        Self {            context_manager,            scheduler_slot: None,            job_manager: None,            store: None,            event_tx: None,            inject_tx: None,            secrets_store: None,        }    }    /// Inject sandbox dependencies so `create_job` delegates to Docker containers.    pub fn with_sandbox(        mut self,        job_manager: Arc<ContainerJobManager>,        store: Option<Arc<dyn Database>>,    ) -> Self {        self.job_manager = Some(job_manager);        self.store = store;        self    }    /// Inject monitor dependencies so fire-and-forget jobs spawn a background    /// monitor that forwards Claude Code output to the main agent loop.    pub fn with_monitor_deps(        mut self,        event_tx: tokio::sync::broadcast::Sender<(Uuid, SseEvent)>,        inject_tx: tokio::sync::mpsc::Sender<IncomingMessage>,    ) -> Self {        self.event_tx = Some(event_tx);        self.inject_tx = Some(inject_tx);        self    }    /// Inject a lazy scheduler slot for dispatching local (non-sandbox) jobs.    pub fn with_scheduler_slot(mut self, slot: SchedulerSlot) -> Self {        self.scheduler_slot = Some(slot);        self    }    /// Inject secrets store for credential validation.    pub fn with_secrets(mut self, secrets: Arc<dyn SecretsStore + Send + Sync>) -> Self {        self.secrets_store = Some(secrets);        self    }    pub fn sandbox_enabled(&self) -> bool {        self.job_manager.is_some()    }    /// Parse and validate the `credentials` parameter.    ///    /// Each key is a secret name (must exist in SecretsStore), each value is the    /// env var name the container should receive it as. Returns an empty vec if    /// no credentials were requested.    async fn parse_credentials(        &self,        params: &serde_json::Value,        user_id: &str,    ) -> Result<Vec<CredentialGrant>, ToolError> {        let creds_obj = match params.get("credentials").and_then(|v| v.as_object()) {            Some(obj) if !obj.is_empty() => obj,            _ => return Ok(vec![]),        };        const MAX_CREDENTIAL_GRANTS: usize = 20;        if creds_obj.len() > MAX_CREDENTIAL_GRANTS {            return Err(ToolError::InvalidParameters(format!(                "too many credential grants ({}, max {})",                creds_obj.len(),                MAX_CREDENTIAL_GRANTS            )));        }        let secrets = match &self.secrets_store {            Some(s) => s,            None => {                return Err(ToolError::ExecutionFailed(                    "credentials requested but no secrets store is configured. \                     Set SECRETS_MASTER_KEY to enable credential management."                        .to_string(),                ));            }        };        let mut grants = Vec::with_capacity(creds_obj.len());        for (secret_name, env_var_value) in creds_obj {            let env_var = env_var_value.as_str().ok_or_else(|| {                ToolError::InvalidParameters(format!(                    "credential env var for '{}' must be a string",                    secret_name                ))            })?;            validate_env_var_name(env_var)?;            // Validate the secret actually exists            let exists = secrets.exists(user_id, secret_name).await.map_err(|e| {                ToolError::ExecutionFailed(format!(                    "failed to check secret '{}': {}",                    secret_name, e                ))            })?;            if !exists {                return Err(ToolError::ExecutionFailed(format!(                    "secret '{}' not found. Store it first via 'ironclaw tool auth' or the web UI.",                    secret_name                )));            }            grants.push(CredentialGrant {                secret_name: secret_name.clone(),                env_var: env_var.to_string(),            });        }        Ok(grants)    }    /// Persist a sandbox job record (fire-and-forget).    fn persist_job(&self, record: SandboxJobRecord) {        if let Some(store) = self.store.clone() {            tokio::spawn(async move {                if let Err(e) = store.save_sandbox_job(&record).await {                    tracing::warn!(job_id = %record.id, "Failed to persist sandbox job: {}", e);                }            });        }    }    /// Update sandbox job status in DB (fire-and-forget).    fn update_status(        &self,        job_id: Uuid,        status: &str,        success: Option<bool>,        message: Option<String>,        started_at: Option<chrono::DateTime<Utc>>,        completed_at: Option<chrono::DateTime<Utc>>,    ) {        if let Some(store) = self.store.clone() {            let status = status.to_string();            tokio::spawn(async move {                if let Err(e) = store                    .update_sandbox_job_status(                        job_id,                        &status,                        success,                        message.as_deref(),                        started_at,                        completed_at,                    )                    .await                {                    tracing::warn!(job_id = %job_id, "Failed to update sandbox job status: {}", e);                }            });        }    }    /// Execute via Scheduler (persists to DB + spawns worker), or fall back to    /// ContextManager-only if the scheduler isn't available yet.    async fn execute_local(        &self,        title: &str,        description: &str,        ctx: &JobContext,    ) -> Result<ToolOutput, ToolError> {        let start = std::time::Instant::now();        // Use the scheduler if available — creates in ContextManager, persists        // to DB, transitions to InProgress, and spawns a worker. The new job        // runs independently with its own Worker and LLM context (not inheriting        // the parent conversation). MaxJobsExceeded is returned as error JSON        // so the LLM can report it to the user.        if let Some(ref slot) = self.scheduler_slot            && let Some(ref scheduler) = *slot.read().await        {            return match scheduler                .dispatch_job(&ctx.user_id, title, description, None)                .await            {                Ok(job_id) => {                    let result = serde_json::json!({                        "job_id": job_id.to_string(),                        "title": title,                        "status": "in_progress",                        "message": format!("Created and scheduled job '{}'", title)                    });                    Ok(ToolOutput::success(result, start.elapsed()))                }                Err(e) => {                    let result = serde_json::json!({                        "error": e.to_string()                    });                    Ok(ToolOutput::success(result, start.elapsed()))                }            };        }        // Fallback: ContextManager-only (scheduler not yet initialized).        match self            .context_manager            .create_job_for_user(&ctx.user_id, title, description)            .await        {            Ok(job_id) => {                let result = serde_json::json!({                    "job_id": job_id.to_string(),                    "title": title,                    "status": "pending",                    "message": format!("Created job '{}' (not scheduled — scheduler unavailable)", title)                });                Ok(ToolOutput::success(result, start.elapsed()))            }            Err(e) => {                let result = serde_json::json!({                    "error": e.to_string()                });                Ok(ToolOutput::success(result, start.elapsed()))            }        }    }    /// Execute via sandboxed Docker container.    async fn execute_sandbox(        &self,        task: &str,        explicit_dir: Option<PathBuf>,        wait: bool,        mode: JobMode,        credential_grants: Vec<CredentialGrant>,        ctx: &JobContext,    ) -> Result<ToolOutput, ToolError> {        let start = std::time::Instant::now();        let jm = self.job_manager.as_ref().ok_or_else(|| {            ToolError::ExecutionFailed(                "Sandbox execution requires a configured job manager (container runtime not available)".to_string(),            )        })?;        let job_id = Uuid::new_v4();        let (project_dir, browse_id) = resolve_project_dir(explicit_dir, job_id)?;        let project_dir_str = project_dir.display().to_string();        // Serialize credential grants so restarts can reload them.        let credential_grants_json = match serde_json::to_string(&credential_grants) {            Ok(json) => json,            Err(e) => {                tracing::warn!(                    "Failed to serialize credential grants for job {}: {}. \                     Grants will not survive a restart.",                    job_id,                    e                );                String::from("[]")            }        };        // Persist the job to DB before creating the container.        self.persist_job(SandboxJobRecord {            id: job_id,            task: task.to_string(),            status: "creating".to_string(),            user_id: ctx.user_id.clone(),            project_dir: project_dir_str.clone(),            success: None,            failure_reason: None,            created_at: Utc::now(),            started_at: None,            completed_at: None,            credential_grants_json,        });        // Persist the job mode to DB        if mode == JobMode::ClaudeCode            && let Some(store) = self.store.clone()        {            let job_id_copy = job_id;            tokio::spawn(async move {                if let Err(e) = store                    .update_sandbox_job_mode(job_id_copy, "claude_code")                    .await                {                    tracing::warn!(job_id = %job_id_copy, "Failed to set job mode: {}", e);                }            });        }        // Create the container job with the pre-determined job_id.        let _token = jm            .create_job(job_id, task, Some(project_dir), mode, credential_grants)            .await            .map_err(|e| {                self.update_status(                    job_id,                    "failed",                    Some(false),                    Some(e.to_string()),                    None,                    Some(Utc::now()),                );                ToolError::ExecutionFailed(format!("failed to create container: {}", e))            })?;        // Container started successfully.        let now = Utc::now();        self.update_status(job_id, "running", None, None, Some(now), None);        if !wait {            // Spawn a background monitor that forwards Claude Code output            // into the main agent loop.            //            // This monitor is intentionally fire-and-forget: its lifetime is            // bound to the broadcast channel (etx) and the inject sender (itx).            // When the broadcast sender is dropped during shutdown the            // subscription closes and the monitor exits. Likewise, if the agent            // loop stops consuming from inject_tx the send will fail and the            // monitor terminates. No JoinHandle is retained.            if let (Some(etx), Some(itx)) = (&self.event_tx, &self.inject_tx) {                if let Some(route) = monitor_route_from_ctx(ctx) {                    crate::agent::job_monitor::spawn_job_monitor(                        job_id,                        etx.subscribe(),                        itx.clone(),                        route,                    );                } else {                    tracing::debug!(                        job_id = %job_id,                        "Skipping job monitor injection due to missing route metadata"                    );                }            }            let result = serde_json::json!({                "job_id": job_id.to_string(),                "status": "started",                "message": "Container started. Use job_events to check status or job_prompt to send follow-up instructions.",                "project_dir": project_dir_str,                "browse_url": format!("/projects/{}", browse_id),            });            return Ok(ToolOutput::success(result, start.elapsed()));        }        // Wait for completion by polling the container state.        let timeout = Duration::from_secs(600);        let poll_interval = Duration::from_secs(2);        let deadline = tokio::time::Instant::now() + timeout;        loop {            if tokio::time::Instant::now() > deadline {                let _ = jm.stop_job(job_id).await;                jm.cleanup_job(job_id).await;                self.update_status(                    job_id,                    "failed",                    Some(false),                    Some("Timed out (10 minutes)".to_string()),                    None,                    Some(Utc::now()),                );                return Err(ToolError::ExecutionFailed(                    "container execution timed out (10 minutes)".to_string(),                ));            }            match jm.get_handle(job_id).await {                Some(handle) => match handle.state {                    crate::orchestrator::job_manager::ContainerState::Running                    | crate::orchestrator::job_manager::ContainerState::Creating => {                        tokio::time::sleep(poll_interval).await;                    }                    crate::orchestrator::job_manager::ContainerState::Stopped => {                        let message = handle                            .completion_result                            .as_ref()                            .and_then(|r| r.message.clone())                            .unwrap_or_else(|| "Container job completed".to_string());                        let success = handle                            .completion_result                            .as_ref()                            .map(|r| r.success)                            .unwrap_or(true);                        jm.cleanup_job(job_id).await;                        let finished_at = Utc::now();                        if success {                            self.update_status(                                job_id,                                "completed",                                Some(true),                                None,                                None,                                Some(finished_at),                            );                            let result = serde_json::json!({                                "job_id": job_id.to_string(),                                "status": "completed",                                "output": message,                                "project_dir": project_dir_str,                                "browse_url": format!("/projects/{}", browse_id),                            });                            return Ok(ToolOutput::success(result, start.elapsed()));                        } else {                            self.update_status(                                job_id,                                "failed",                                Some(false),                                Some(message.clone()),                                None,                                Some(finished_at),                            );                            return Err(ToolError::ExecutionFailed(format!(                                "container job failed: {}",                                message                            )));                        }                    }                    crate::orchestrator::job_manager::ContainerState::Failed => {                        let message = handle                            .completion_result                            .as_ref()                            .and_then(|r| r.message.clone())                            .unwrap_or_else(|| "unknown failure".to_string());                        jm.cleanup_job(job_id).await;                        self.update_status(                            job_id,                            "failed",                            Some(false),                            Some(message.clone()),                            None,                            Some(Utc::now()),                        );                        return Err(ToolError::ExecutionFailed(format!(                            "container job failed: {}",                            message                        )));                    }                },                None => {                    self.update_status(                        job_id,                        "completed",                        Some(true),                        None,                        None,                        Some(Utc::now()),                    );                    let result = serde_json::json!({                        "job_id": job_id.to_string(),                        "status": "completed",                        "output": "Container job completed",                        "project_dir": project_dir_str,                        "browse_url": format!("/projects/{}", browse_id),                    });                    return Ok(ToolOutput::success(result, start.elapsed()));                }            }        }    }}/// The base directory where all project directories must live./// Env var names that could be abused to hijack process behavior.const DANGEROUS_ENV_VARS: &[&str] = &[    // Dynamic linker hijacking    "LD_PRELOAD",    "LD_LIBRARY_PATH",    "LD_AUDIT",    "DYLD_INSERT_LIBRARIES",    "DYLD_LIBRARY_PATH",    // Shell behavior    "BASH_ENV",    "ENV",    "CDPATH",    "IFS",    "PATH",    "HOME",    // Language runtime library path hijacking    "PYTHONPATH",    "NODE_PATH",    "PERL5LIB",    "RUBYLIB",    "CLASSPATH",    // JVM injection    "JAVA_TOOL_OPTIONS",    "MAVEN_OPTS",    "USER",    "SHELL",    "RUST_LOG",];/// Validate that an env var name is safe for container injection.fn validate_env_var_name(name: &str) -> Result<(), ToolError> {    if name.is_empty() {        return Err(ToolError::InvalidParameters(            "env var name cannot be empty".into(),        ));    }    // Must match ^[A-Z_][A-Z0-9_]*$    let valid = name        .bytes()        .enumerate()        .all(|(i, b)| matches!(b, b'A'..=b'Z' | b'_') || (i > 0 && b.is_ascii_digit()));    if !valid {        return Err(ToolError::InvalidParameters(format!(            "env var '{}' must match [A-Z_][A-Z0-9_]* (uppercase, underscores, digits)",            name        )));    }    if DANGEROUS_ENV_VARS.contains(&name) {        return Err(ToolError::InvalidParameters(format!(            "env var '{}' is on the denylist (could hijack process behavior)",            name        )));    }    Ok(())}fn projects_base() -> PathBuf {    ironclaw_base_dir().join("projects")}/// Resolve the project directory, creating it if it doesn't exist.////// Auto-creates `~/.ironclaw/projects/{project_id}/` so every sandbox job has a/// persistent bind mount that survives container teardown.////// When an explicit path is provided (e.g. job restarts reusing the old dir),/// it is validated to fall within `~/.ironclaw/projects/` after canonicalization.